#include <bits/stdc++.h>
using namespace std;

long long a[9];

struct SHelper {
    istream* in;
    void Init() {
        in = &cin;
    }
    long long ReadInt64() {
        long long n;
        (*in) >> n;
        return n;
    }
};

SHelper helper;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    helper.Init();

    for (unsigned long long k = 1; k <= 8; k++) {
        unsigned long long l = (1ULL << k) - 1;
        unsigned long long r = 1ULL << (k - 1);
        unsigned long long v = l * r;
        a[k] = static_cast<long long>(v);
    }

    long long n = helper.ReadInt64();
    for (long long k = 8; k >= 1; k--) {
        if (n >= a[k] && n % a[k] == 0) {
            cout << a[k] << '\n';
            return 0;
        }
    }
    return 0;
}

